tests:
from solution import fizzbuzz

def test_first_five():
    assert fizzbuzz(5) == ["1", "2", "Fizz", "4", "Buzz"]

def test_fifteen():
    assert fizzbuzz(15)[-1] == "FizzBuzz"

def test_length_and_zero():
    assert len(fizzbuzz(30)) == 30
    assert fizzbuzz(0) == []

from solution import add

def test_small():
    assert add(2, 3) == 5

def test_negative():
    assert add(-1, -4) == -5
